const tylkoyCyfry = /^\d+$/;
console.log(tylkoyCyfry.test("12345")); // true
console.log(tylkoyCyfry.test("12a45")); // false

const kodPocztowy = /^\d{2}-\d{3}$/;
console.log(kodPocztowy.test("00-950")); // true
console.log(kodPocztowy.test("00950"));  // false

const tekst = "Ala ma kota i psa";
const slowa = tekst.match(/\w+/g);
console.log(slowa); // ["Ala", "ma", "kota", "i", "psa"]

const tekst = "kontakt: jan@firma.pl lub anna@test.com";
const emaile = tekst.match(/[^\s@]+@[^\s@]+\.[^\s@]+/g);
console.log(emaile); // ["jan@firma.pl", "anna@test.com"]

const tekst = "a=1 b=2 c=3";
const regex = /(\w+)=(\d+)/g;

for (const match of tekst.matchAll(regex)) {
  console.log(`${match[1]}: ${match[2]}`);
}
// "a: 1"
// "b: 2"
// "c: 3"

const regex = /(\d{2}):(\d{2})/;
const match = regex.exec("Spotkanie o 14:30");
console.log(`Godzina: ${match[1]}, Minuty: ${match[2]}`); // "Godzina: 14, Minuty: 30"

const regex = /(?<day>\d{2})\.(?<month>\d{2})\.(?<year>\d{4})/;
const match = regex.exec("Data: 12.07.2026");
console.log(match.groups); // { day: "12", month: "07", year: "2026" }

